# failing line: assert triangle_area(b + c, b, c) == -1
def reference_area(a, b, c):
    if a + b <= c or a + c <= b or b + c <= a:
        return -1
    p = (a + b + c) / 2
    return round(math.sqrt(p * (p - a) * (p - b) * (p - c)), 2)

@given(
    b=st.floats(min_value=0.5, max_value=10, allow_nan=False, allow_infinity=False),
    c=st.floats(min_value=0.5, max_value=10, allow_nan=False, allow_infinity=False),
)
def test_degenerate_sum_equals_third_is_invalid(b, c):
    # boundary: sum of two sides exactly equals third -> not > so invalid
    assert triangle_area(b + c, b, c) == -1
    assert triangle_area(b, b + c, c) == -1
    assert triangle_area(b, c, b + c) == -1
